import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function DashboardHome() {
  const [stats, setStats] = useState({
    totalEmployees: 0,
    departments: 0,
    totalSalary: 0,
    attendanceRate: 0
  });
  const [recentEmployees, setRecentEmployees] = useState([]);

  useEffect(() => {
    fetch(`${API}/employees`)
      .then(res => res.json())
      .then(data => {
        setStats(prev => ({ ...prev, totalEmployees: data.length }));
        setRecentEmployees(data.slice(-5).reverse());
      })
      .catch(() => {});

    fetch(`${API}/departments`)
      .then(res => res.json())
      .then(data => setStats(prev => ({ ...prev, departments: data.length })))
      .catch(() => {});

    // Lấy payroll summary từ MySQL
    fetch(`${API}/payroll-summary`)
      .then(res => res.json())
      .then(data => {
        setStats(prev => ({
          ...prev,
          totalSalary: data.totalNetSalary || 0,
          attendanceRate: data.attendanceRate || 0
        }));
      })
      .catch(() => {});
  }, []);

  const formatVND = (n) => n.toLocaleString('vi-VN') + ' ₫';

  const kpiCards = [
    {
      icon: '👥', label: 'Tổng Nhân Viên', value: stats.totalEmployees,
      change: 'Từ SQL Server', color: '#4f46e5', bg: 'rgba(79,70,229,0.1)'
    },
    {
      icon: '🏢', label: 'Phòng Ban', value: stats.departments,
      change: 'Từ SQL Server', color: '#0ea5e9', bg: 'rgba(14,165,233,0.1)'
    },
    {
      icon: '💰', label: 'Tổng Chi Lương',
      value: stats.totalSalary > 0 ? formatVND(stats.totalSalary) : '---',
      change: stats.totalSalary > 0 ? 'Từ MySQL Payroll' : 'Chưa có dữ liệu',
      color: '#10b981', bg: 'rgba(16,185,129,0.1)'
    },
    {
      icon: '📅', label: 'Tỷ Lệ Chấm Công',
      value: stats.attendanceRate > 0 ? stats.attendanceRate + '%' : '---',
      change: stats.attendanceRate > 0 ? 'Từ MySQL Payroll' : 'Chưa có dữ liệu',
      color: '#f59e0b', bg: 'rgba(245,158,11,0.1)'
    }
  ];

  return (
    <div className="animate-fade-in">
      {/* KPI Cards */}
      <div className="row g-3 mb-4">
        {kpiCards.map((card, i) => (
          <div className="col-md-6 col-xl-3" key={i}>
            <div className="stat-card">
              <div className="d-flex justify-content-between align-items-start mb-3">
                <div className="stat-icon" style={{ background: card.bg, color: card.color }}>
                  {card.icon}
                </div>
              </div>
              <div className="stat-value" style={{ color: card.color }}>{card.value}</div>
              <div className="stat-label">{card.label}</div>
              <div className="stat-change text-muted mt-2">
                {card.change}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Quick Actions */}
      <div className="row g-3">
        <div className="col-lg-8">
          <div className="content-card">
            <div className="card-header-custom">
              <h5>📋 Nhân Viên Mới Nhất</h5>
            </div>
            <div className="p-3">
              <div className="table-responsive">
                <table className="table table-custom">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Họ Tên</th>
                      <th>Phòng Ban</th>
                      <th>Chức Vụ</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentEmployees.length === 0 ? (
                      <tr>
                        <td colSpan="4" className="text-center text-muted py-4">
                          Kết nối Backend để xem dữ liệu
                        </td>
                      </tr>
                    ) : (
                      recentEmployees.map(e => (
                        <tr key={e.EmployeeID}>
                          <td><strong>#{e.EmployeeID}</strong></td>
                          <td>{e.FullName}</td>
                          <td>{e.Department}</td>
                          <td>{e.Position}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>

        <div className="col-lg-4">
          <div className="content-card">
            <div className="card-header-custom">
              <h5>🔔 Cảnh Báo Hệ Thống</h5>
            </div>
            <div className="p-3">
              <p className="text-center text-muted py-3">Chưa có cảnh báo</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default DashboardHome;
